/* Generated by `npm run db:seed-sql` from the files in src/data. Run AFTER schema.sql.
   Idempotent: re-running updates the catalog in place. */

SET XACT_ABORT ON;
SET NOCOUNT ON;
BEGIN TRANSACTION;
MERGE dbo.Experiences AS target
USING (VALUES
  (N'scuba-diving', N'Scuba Diving', N'Grande Island, Goa', N'Adventure', 4.8, 4200, N'₹4,200', N'3 hours', N'https://images.unsplash.com/photo-1682687982049-b3d433368cd1?auto=format&fit=crop&q=80&w=1200&crop=entropy', N'A shallow-reef dive suited to first-timers, with a certified instructor at your side the entire way down. Expect parrotfish, the odd reef shark sighting, and a wreck just deep enough to feel like an adventure.', 0),
  (N'mountain-trekking', N'Mountain Trekking', N'Solang Valley, Manali', N'Adventure', 4.7, 2800, N'₹2,800', N'Full day', N'https://images.unsplash.com/photo-1760716190527-c36474a2dd2f?auto=format&fit=crop&q=80&w=1200&crop=entropy', N'A guided ridge trail above the tree line, climbing through pine forest before opening onto views of the Pir Panjal range. Moderate difficulty — sturdy shoes and a head for switchbacks recommended.', 1),
  (N'sunset-kayaking', N'Sunset Kayaking', N'Palolem Bay, Goa', N'Adventure', 4.9, 1800, N'₹1,800', N'2 hours', N'https://images.unsplash.com/photo-1436162716854-dcb9157bfac1?auto=format&fit=crop&q=80&w=1200&crop=entropy', N'A calm-water paddle out toward the bay''s edge, timed to finish exactly as the sky turns copper. Bioluminescent plankton light the water on moonless nights between November and February.', 2),
  (N'heritage-walk', N'Heritage Walk', N'Old City, Jaipur', N'Culture', 4.6, 1200, N'₹1,200', N'3 hours', N'https://images.unsplash.com/photo-1722577359782-265eb6282c26?auto=format&fit=crop&q=80&w=1200&crop=faces', N'A slow morning walk through the walled Pink City with a local historian — block-print workshops, spice merchants, and the quiet inner courtyards most visitors walk straight past.', 3),
  (N'food-tour', N'Food Tour', N'Fort Kochi, Kerala', N'Food', 4.8, 1500, N'₹1,500', N'3 hours', N'https://images.unsplash.com/photo-1750949135629-0345e050c353?auto=format&fit=crop&q=80&w=1200&crop=entropy', N'Six stops, one appetite. From banana-leaf thali to fresh-caught seafood grilled streetside, this tour trades restaurant menus for the stalls locals actually queue at.', 4),
  (N'wildlife-safari', N'Wildlife Safari', N'Ranthambore National Park', N'Nature', 4.7, 3500, N'₹3,500', N'Half day', N'https://images.unsplash.com/photo-1575445829782-63457401b336?auto=format&fit=crop&q=80&w=1200&crop=entropy', N'An open-jeep safari through dry deciduous forest and lake-fed grassland, tracking Bengal tigers alongside sloth bears, marsh crocodiles, and over 300 recorded bird species.', 5)
) AS source (Id, Name, Location, Category, Rating, Price, PriceLabel, Duration, ImageUrl, Description, SortOrder)
ON target.Id = source.Id
WHEN MATCHED THEN UPDATE SET
  Name = source.Name,
  Location = source.Location,
  Category = source.Category,
  Rating = source.Rating,
  Price = source.Price,
  PriceLabel = source.PriceLabel,
  Duration = source.Duration,
  ImageUrl = source.ImageUrl,
  Description = source.Description,
  SortOrder = source.SortOrder,
  UpdatedAt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN
  INSERT (Id, Name, Location, Category, Rating, Price, PriceLabel, Duration, ImageUrl, Description, SortOrder) VALUES (source.Id, source.Name, source.Location, source.Category, source.Rating, source.Price, source.PriceLabel, source.Duration, source.ImageUrl, source.Description, source.SortOrder);

MERGE dbo.Stays AS target
USING (VALUES
  (N'cliff-house-goa', N'The Cliff House', N'Ashwem, North Goa', N'Luxury', 4.9, 12500, N'₹12,500 / night', N'https://images.unsplash.com/photo-1763402084622-c7da69907b81?auto=format&fit=crop&q=80&w=1400&crop=entropy', 0),
  (N'kumarakom-houseboat', N'Kumarakom Heritage Houseboat', N'Vembanad Lake, Kerala', N'Nature', 4.8, 9800, N'₹9,800 / night', N'https://images.unsplash.com/photo-1785932413547-cdd1159e1f1e?auto=format&fit=crop&q=80&w=1400&crop=bottom', 1),
  (N'ubud-canopy-villas', N'Ubud Canopy Villas', N'Ubud, Bali', N'Luxury', 4.9, 15200, N'₹15,200 / night', N'https://images.unsplash.com/photo-1753724933350-c2e0e2990445?auto=format&fit=crop&q=80&w=1400&crop=entropy', 2),
  (N'desert-retreat-dubai', N'Al Marmoom Desert Retreat', N'Al Marmoom, Dubai', N'Luxury', 4.7, 21000, N'₹21,000 / night', N'https://images.unsplash.com/photo-1748626083682-611d0a66cb50?auto=format&fit=crop&q=80&w=1400&crop=bottom', 3)
) AS source (Id, Name, Location, Category, Rating, Price, PriceLabel, ImageUrl, SortOrder)
ON target.Id = source.Id
WHEN MATCHED THEN UPDATE SET
  Name = source.Name,
  Location = source.Location,
  Category = source.Category,
  Rating = source.Rating,
  Price = source.Price,
  PriceLabel = source.PriceLabel,
  ImageUrl = source.ImageUrl,
  SortOrder = source.SortOrder,
  UpdatedAt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN
  INSERT (Id, Name, Location, Category, Rating, Price, PriceLabel, ImageUrl, SortOrder) VALUES (source.Id, source.Name, source.Location, source.Category, source.Rating, source.Price, source.PriceLabel, source.ImageUrl, source.SortOrder);

MERGE dbo.Destinations AS target
USING (VALUES
  (N'goa', N'Goa', N'India', N'GOA', N'15.29°N 74.12°E', N'Sun-bleached shores and slow afternoons', N'7 beaches · 3 night markets', N'Beaches', 4.7, 18500, N'₹18,500', N'4–6 days', N'https://images.unsplash.com/photo-1727276884218-ec3be46cda91?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'Goa trades in golden light and unhurried time — Portuguese-tiled churches, spice-scented lanes, and a coastline that shifts from beach-shack calm in the south to laterite cliffs in the north. Days drift between hammocks and headlands; nights end at a table set right on the sand.', N'November – February', N'₹15,000 – ₹35,000 for 5 days', 0),
  (N'kerala', N'Kerala', N'India', N'KOC', N'9.49°N 76.34°E', N'God''s Own Country, one canal at a time', N'900km of backwaters', N'Nature', 4.8, 24000, N'₹24,000', N'5–7 days', N'https://images.unsplash.com/photo-1785932413547-cdd1159e1f1e?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'A green hush settles over Kerala the moment a houseboat leaves the jetty. Palm-lined backwaters open onto paddy fields and spice plantations, and the pace of the day is set by the water itself — slow, reflective, and entirely worth it.', N'September – March', N'₹20,000 – ₹45,000 for 6 days', 1),
  (N'manali', N'Manali', N'Himachal Pradesh, India', N'MNL', N'32.24°N 77.19°E', N'Pine air and snow-line horizons', N'2,050m elevation', N'Mountains', 4.6, 16000, N'₹16,000', N'4–5 days', N'https://images.unsplash.com/photo-1677820915334-d7ceba1e844a?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'Manali sits where the Beas River meets the first serious rise of the Himalayas. Old Manali keeps its cafe-and-cobblestone charm, while Solang and Rohtang push the horizon higher — paragliders overhead, cedar forests below, and snow that lingers well into spring.', N'March – June, or December for snow', N'₹12,000 – ₹28,000 for 5 days', 2),
  (N'jaipur', N'Jaipur', N'Rajasthan, India', N'JAI', N'26.92°N 75.82°E', N'The Pink City, carved in sandstone', N'3 forts · 1 walled old city', N'Culture', 4.7, 14000, N'₹14,000', N'3–4 days', N'https://images.unsplash.com/photo-1722577359782-265eb6282c26?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'Jaipur announces itself in terracotta pink — the honeycomb screens of Hawa Mahal, the geometry of Jantar Mantar, and a walled old city still trading in lac bangles and block-printed cotton. Amber Fort waits just beyond the edge of town, half palace and half hilltop fortress.', N'October – March', N'₹10,000 – ₹22,000 for 4 days', 3),
  (N'bali', N'Bali', N'Indonesia', N'DPS', N'8.34°S 115.09°E', N'Rice terraces stacked toward the sky', N'10,000+ temples', N'Beaches', 4.9, 42000, N'₹42,000', N'6–8 days', N'https://images.unsplash.com/photo-1557093793-d149a38a1be8?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'Bali layers jungle, temple, and shoreline within a single afternoon''s drive. Ubud keeps its terraced rice fields and incense-lit courtyards; the south coast trades that quiet for surf breaks and cliffside sunsets. Between the two lies most of what makes the island worth the flight.', N'April – October', N'₹35,000 – ₹80,000 for 7 days', 4),
  (N'dubai', N'Dubai', N'United Arab Emirates', N'DXB', N'25.20°N 55.27°E', N'Desert horizon, vertical skyline', N'Tallest building on Earth', N'Luxury', 4.6, 65000, N'₹65,000', N'4–6 days', N'https://images.unsplash.com/photo-1748626083682-611d0a66cb50?auto=format&fit=crop&q=80&w=1400&crop=entropy', N'Dubai builds upward and outward at once — Burj Khalifa piercing the haze above a city that was mostly desert two generations ago. Beyond the skyline sit gold souks, a restored creekside old town, and dunes close enough for a sunset drive.', N'November – March', N'₹55,000 – ₹1,20,000 for 5 days', 5)
) AS source (Id, Name, Region, Code, Coords, Tagline, Metadata, Category, Rating, Price, PriceLabel, Duration, ImageUrl, Description, BestTime, Budget, SortOrder)
ON target.Id = source.Id
WHEN MATCHED THEN UPDATE SET
  Name = source.Name,
  Region = source.Region,
  Code = source.Code,
  Coords = source.Coords,
  Tagline = source.Tagline,
  Metadata = source.Metadata,
  Category = source.Category,
  Rating = source.Rating,
  Price = source.Price,
  PriceLabel = source.PriceLabel,
  Duration = source.Duration,
  ImageUrl = source.ImageUrl,
  Description = source.Description,
  BestTime = source.BestTime,
  Budget = source.Budget,
  SortOrder = source.SortOrder,
  UpdatedAt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN
  INSERT (Id, Name, Region, Code, Coords, Tagline, Metadata, Category, Rating, Price, PriceLabel, Duration, ImageUrl, Description, BestTime, Budget, SortOrder) VALUES (source.Id, source.Name, source.Region, source.Code, source.Coords, source.Tagline, source.Metadata, source.Category, source.Rating, source.Price, source.PriceLabel, source.Duration, source.ImageUrl, source.Description, source.BestTime, source.Budget, source.SortOrder);

