INSERT INTO dbo.DestinationTips (DestinationId, Position, Tip) VALUES
  (N'goa', 0, N'Rent a scooter for the coast road — the bus network skips the best beaches.'),
  (N'goa', 1, N'Book beach shacks a season ahead in December and January.'),
  (N'kerala', 0, N'A one-night houseboat stay is plenty — book two nights only if you want total disconnection.'),
  (N'kerala', 1, N'Monsoon season (June–August) brings dramatically lower prices and lush green backwaters.'),
  (N'manali', 0, N'Rohtang Pass requires a permit in peak season — arrange it a day ahead.'),
  (N'manali', 1, N'Pack layers; mornings in the valley are cold even in summer.'),
  (N'jaipur', 0, N'Enter Amber Fort by 8am to beat both the heat and the tour buses.'),
  (N'jaipur', 1, N'A single composite ticket covers most of the city''s monuments — worth buying on day one.'),
  (N'bali', 0, N'Base yourself in Ubud for culture, Canggu or Uluwatu for beach and surf — few travelers love both equally.'),
  (N'bali', 1, N'A local sarong is required to enter most temples; many rent them at the gate.'),
  (N'dubai', 0, N'Dress modestly outside tourist zones and resorts — it''s appreciated, not just required.'),
  (N'dubai', 1, N'Book desert safaris for late afternoon to catch both the dunes and the sunset.');

